 "content": "def transform(grid):
    # Keep the 3-valued background pattern and overlay a translated copy of
    # the sparse marker pattern at the unique valid offset, recoloring 3s.
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v not in (0, 3)}
    color = next(iter(colors))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    shifts = []
    for dr in range(-h + 1, h):
        for dc in range(-w + 1, w):
            if dr == 0 and dc == 0:
                continue
            shifted = [(r + dr, c + dc) for r, c in pts]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] in (0, color) for r, c in shifted):
                shifts.append((dr, dc, shifted))
    if not shifts:
        return [row[:] for row in grid]
    # Valid translations are constrained by all source marks; select the
    # translation covering the largest number of non-background cells.
    dr, dc, shifted = max(shifts, key=lambda item: sum(grid[r][c] == color for r, c in item[2]))
    out = [row[:] for row in grid]
    for r, c in shifted:
        out[r][c] = color
    return out

